package com.example._0zo.model;

import com.example._0zo.model.enums.Rank;
import com.example._0zo.model.enums.Suit;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class CardTest {

    @Test
    void testGetValue_NumberAndFaceCards() {
        Card two = new Card(Suit.CLUBS, Rank.TWO);
        Card ten = new Card(Suit.HEARTS, Rank.TEN);
        Card jack = new Card(Suit.SPADES, Rank.JACK);

        assertEquals(2, two.getValue(0));
        assertEquals(10, ten.getValue(0));
        assertEquals(-10, jack.getValue(0));
    }

    @Test
    void testAceResolvesToTenWhenFitsOtherwiseOne() {
        Card ace = new Card(Suit.DIAMONDS, Rank.ACE);

        // fits as 10
        assertEquals(10, ace.getValue(30));

        // does not fit as 10 -> becomes 1
        assertEquals(1, ace.getValue(45));
    }

    @Test
    void testIsPlayable() {
        Card ten = new Card(Suit.HEARTS, Rank.TEN);
        Card ace = new Card(Suit.SPADES, Rank.ACE);

        assertTrue(ten.isPlayable(30)); // 30+10 <=50
        assertFalse(ten.isPlayable(45)); // 45+10 > 50

        // ace as 10 fits
        assertTrue(ace.isPlayable(30));
        // ace as 1 also fits when 50 would be exceeded by 10
        assertTrue(ace.isPlayable(50 - 1));
    }
}

package com.example._0zo.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class DeckTest {

    @Test
    void initialDeckHas52Cards() {
        Deck deck = new Deck();
        assertEquals(52, deck.size());
    }

    @Test
    void drawReducesSize() {
        Deck deck = new Deck();
        int before = deck.size();
        Card c = deck.draw();
        assertNotNull(c);
        assertEquals(before - 1, deck.size());
    }
}

package com.example._0zo.model;

import com.example._0zo.model.enums.Rank;
import com.example._0zo.model.enums.Suit;
import com.example._0zo.model.exceptions.GameOverException;
import com.example._0zo.model.exceptions.InvalidMoveException;
import com.example._0zo.model.game.GameEngine;
import com.example._0zo.model.players.HumanPlayer;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class GameEngineTest {

    @Test
    void setupGameDealsAndPlacesInitialCard() throws InvalidMoveException {
        HumanPlayer p1 = new HumanPlayer("A");
        HumanPlayer p2 = new HumanPlayer("B");
        GameEngine engine = new GameEngine(List.of(p1, p2));

        engine.setupGame();

        assertEquals(4, p1.getHandSize());
        assertEquals(4, p2.getHandSize());
        assertNotNull(engine.getTopCard());
        assertEquals(52 - (2 * 4) - 1, engine.getDeckSize());
    }

    @Test
    void playHumanCardValidAndInvalid() throws InvalidMoveException, GameOverException {
        HumanPlayer p1 = new HumanPlayer("A");
        HumanPlayer p2 = new HumanPlayer("B");
        GameEngine engine = new GameEngine(List.of(p1, p2));

        // give p1 a series of cards to drive sum to 45
        p1.receiveCard(new Card(Suit.CLUBS, Rank.TEN)); // 10 -> 10
        p1.receiveCard(new Card(Suit.CLUBS, Rank.TEN)); // 10 -> 20
        p1.receiveCard(new Card(Suit.CLUBS, Rank.TEN)); // 10 -> 30
        p1.receiveCard(new Card(Suit.CLUBS, Rank.TEN)); // 10 -> 40
        p1.receiveCard(new Card(Suit.HEARTS, Rank.FIVE)); // 5  -> 45

        // play four tens and a five sequentially
        engine.playHumanCard(p1, p1.getHand().get(0));
        engine.playHumanCard(p1, p1.getHand().get(0));
        engine.playHumanCard(p1, p1.getHand().get(0));
        engine.playHumanCard(p1, p1.getHand().get(0));
        engine.playHumanCard(p1, p1.getHand().get(0));

        assertEquals(45, engine.getTableSum());

        // now playing a TEN should throw InvalidMoveException
        p1.receiveCard(new Card(Suit.DIAMONDS, Rank.TEN));
        Card ten = p1.getHand().stream().filter(c -> c.getRank() == Rank.TEN).findFirst().orElseThrow();
        InvalidMoveException ex = assertThrows(InvalidMoveException.class, () -> engine.playHumanCard(p1, ten));
        assertTrue(ex.getMessage().contains("excedería") || ex.getCurrentSum() == 45);
    }

    @Test
    void eliminateCurrentPlayerWhenCannotPlay() throws GameOverException {
        HumanPlayer p1 = new HumanPlayer("A");
        HumanPlayer p2 = new HumanPlayer("B");
        GameEngine engine = new GameEngine(List.of(p1, p2));

        // ensure current player has no cards
        assertEquals(0, engine.getState().getCurrentPlayer().getHandSize());

        boolean eliminated = engine.eliminateCurrentPlayer();
        assertTrue(eliminated);
        assertFalse(engine.getState().getAllPlayers().get(0).isActive());
    }
}

package com.example._0zo.model;

import com.example._0zo.model.game.GameState;
import com.example._0zo.model.players.HumanPlayer;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class GameStateTest {

    @Test
    void currentPlayerCyclesAndRoundsIncrease() {
        var p1 = new HumanPlayer("p1");
        var p2 = new HumanPlayer("p2");
        GameState state = new GameState(List.of(p1, p2));

        assertEquals(p1, state.getCurrentPlayer());
        state.advanceTurn();
        assertEquals(p2, state.getCurrentPlayer());
        assertEquals(1, state.getTotalRounds());
        state.advanceTurn();
        assertEquals(p1, state.getCurrentPlayer());
        assertEquals(2, state.getTotalRounds());
    }

    @Test
    void isGameOverWhenOneOrZeroActive() {
        var p1 = new HumanPlayer("p1");
        GameState state = new GameState(List.of(p1));
        assertTrue(state.isGameOver());
    }
}

package com.example._0zo.model;

import com.example._0zo.model.enums.Rank;
import com.example._0zo.model.enums.Suit;
import com.example._0zo.model.players.MachinePlayer;
import com.example._0zo.model.exceptions.InvalidMoveException;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class MachinePlayerTest {

    @Test
    void selectCardChoosesLowestResultUnderLimit() throws InvalidMoveException {
        MachinePlayer m = new MachinePlayer("AI");
        Card c1 = new Card(Suit.CLUBS, Rank.TEN); // +10
        Card c2 = new Card(Suit.HEARTS, Rank.SEVEN); // +7
        m.receiveCard(c1);
        m.receiveCard(c2);

        Card chosen = m.selectCard(30); // results: 40 and 37 -> choose 37 (SEVEN)
        assertEquals(c2, chosen);
    }

    @Test
    void selectCardThrowsWhenNoValid() {
        MachinePlayer m = new MachinePlayer("AI");
        // only high cards that will overflow
        m.receiveCard(new Card(Suit.CLUBS, Rank.TEN));
        assertThrows(InvalidMoveException.class, () -> m.selectCard(45));
    }
}

package com.example._0zo.model;

import com.example._0zo.model.enums.Rank;
import com.example._0zo.model.enums.Suit;
import com.example._0zo.model.players.HumanPlayer;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class PlayerTest {

    @Test
    void canPlayDetectsPlayableCard() {
        HumanPlayer p = new HumanPlayer("A");
        p.receiveCard(new Card(Suit.CLUBS, Rank.TWO));
        assertTrue(p.canPlay(49) == false); // 49+2 >50 -> false
        assertTrue(p.canPlay(48)); // 48+2 <=50 -> true
    }

    @Test
    void surrenderHandEmptiesAndReturnsCards() {
        HumanPlayer p = new HumanPlayer("B");
        Card a = new Card(Suit.DIAMONDS, Rank.THREE);
        p.receiveCard(a);
        assertEquals(1, p.getHandSize());
        var surrendered = p.surrenderHand();
        assertEquals(1, surrendered.size());
        assertEquals(0, p.getHandSize());
    }

    @Test
    void eliminateSetsStatus() {
        HumanPlayer p = new HumanPlayer("C");
        assertTrue(p.isActive());
        p.eliminate();
        assertFalse(p.isActive());
    }
}

package com.example._0zo.model;

import com.example._0zo.model.enums.Rank;
import com.example._0zo.model.enums.Suit;
import com.example._0zo.model.exceptions.InvalidMoveException;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class TableTest {

    @Test
    void placeInitialCardUpdatesSumAndTop() throws InvalidMoveException {
        Table table = new Table();
        Card c = new Card(Suit.CLUBS, Rank.TEN); // value 10
        table.placeInitialCard(c);
        assertEquals(10, table.getSum());
        assertEquals(c, table.getTopCard());
    }

    @Test
    void placingCardThatExceedsThrows() {
        Table table = new Table();
        // bring sum to 45
        try {
            table.placeInitialCard(new Card(Suit.CLUBS, Rank.TEN)); // 10
            table.placeInitialCard(new Card(Suit.CLUBS, Rank.TEN)); // 20
            table.placeInitialCard(new Card(Suit.CLUBS, Rank.TEN)); // 30
            table.placeInitialCard(new Card(Suit.CLUBS, Rank.TEN)); // 40
            table.placeInitialCard(new Card(Suit.CLUBS, Rank.FIVE)); // 45
        } catch (InvalidMoveException e) {
            fail("setup failed: " + e.getMessage());
        }

        Card ten = new Card(Suit.HEARTS, Rank.TEN);
        InvalidMoveException ex = assertThrows(InvalidMoveException.class, () -> table.placeInitialCard(ten));
        assertTrue(ex.getMessage().contains("exceed" ) || ex.getCardValue() == 10 || ex.getCurrentSum() == 45);
    }

    @Test
    void collectForRefillKeepsTopAndReturnsOthers() throws InvalidMoveException {
        Table table = new Table();
        table.placeInitialCard(new Card(Suit.CLUBS, Rank.TWO));
        table.placeInitialCard(new Card(Suit.CLUBS, Rank.THREE));
        table.placeInitialCard(new Card(Suit.CLUBS, Rank.FOUR));

        List<Card> collected = table.collectForRefill();
        assertFalse(collected.isEmpty());
        assertEquals(1, table.getPileSize());
        assertEquals(table.getTopCard(), collected.get(collected.size() - 1).equals(table.getTopCard()) ? table.getTopCard() : table.getTopCard());
    }
}
